// BoardServiceHandler is an implementation of the harness.library.v1.BoardService service.
type BoardServiceHandler interface {
	ListBoards(context.Context, *connect.Request[v1.ListBoardsRequest]) (*connect.Response[v1.ListBoardsResponse], error)
	// A board with its stages and cards.
	GetBoard(context.Context, *connect.Request[v1.GetBoardRequest]) (*connect.Response[v1.GetBoardResponse], error)
	CreateBoard(context.Context, *connect.Request[v1.CreateBoardRequest]) (*connect.Response[v1.CreateBoardResponse], error)
	// Replaces the name and the stages. A stage or input that keeps its id keeps its cards and its state. A stage left out takes
	// its cards to the first stage.
	UpdateBoard(context.Context, *connect.Request[v1.UpdateBoardRequest]) (*connect.Response[v1.UpdateBoardResponse], error)
	DeleteBoard(context.Context, *connect.Request[v1.DeleteBoardRequest]) (*connect.Response[v1.DeleteBoardResponse], error)
	// Cards across everything the caller can see, filtered.
	ListCards(context.Context, *connect.Request[v1.ListCardsRequest]) (*connect.Response[v1.ListCardsResponse], error)
	// A card by id or key, with comments and activity, and its linked issue read live when the server holds the connection.
	GetCard(context.Context, *connect.Request[v1.GetCardRequest]) (*connect.Response[v1.GetCardResponse], error)
	CreateCard(context.Context, *connect.Request[v1.CreateCardRequest]) (*connect.Response[v1.CreateCardResponse], error)
	UpdateCard(context.Context, *connect.Request[v1.UpdateCardRequest]) (*connect.Response[v1.UpdateCardResponse], error)
	// FAILED_PRECONDITION when expected_version is set and stale: the card stays where the other mover put it.
	MoveCard(context.Context, *connect.Request[v1.MoveCardRequest]) (*connect.Response[v1.MoveCardResponse], error)
	DeleteCard(context.Context, *connect.Request[v1.DeleteCardRequest]) (*connect.Response[v1.DeleteCardResponse], error)
	// Tries a failed output again.
	RetryCardOutput(context.Context, *connect.Request[v1.RetryCardOutputRequest]) (*connect.Response[v1.RetryCardOutputResponse], error)
	// Attaches an issue, a session, a branch or a pull request to a card. Linking an issue by hand ignores the once-only ledger.
	LinkCard(context.Context, *connect.Request[v1.LinkCardRequest]) (*connect.Response[v1.LinkCardResponse], error)
	// Adds or removes a relation to another card the caller can see.
	RelateCard(context.Context, *connect.Request[v1.RelateCardRequest]) (*connect.Response[v1.RelateCardResponse], error)
	// A comment on the card. With `on_external`, on the linked issue instead, when the server holds the connection;
	// FAILED_PRECONDITION on a device connection, where the client does it.
	CommentCard(context.Context, *connect.Request[v1.CommentCardRequest]) (*connect.Response[v1.CommentCardResponse], error)
	// Removes a comment: its author or those with manage.
	DeleteCardComment(context.Context, *connect.Request[v1.DeleteCardCommentRequest]) (*connect.Response[v1.DeleteCardCommentResponse], error)
	// What a session started from this card should use.
	PrepareCardSession(context.Context, *connect.Request[v1.PrepareCardSessionRequest]) (*connect.Response[v1.PrepareCardSessionResponse], error)
	// Records the PR on every card linked to the session. Nothing happens when there are none.
	LinkSessionPullRequest(context.Context, *connect.Request[v1.LinkSessionPullRequestRequest]) (*connect.Response[v1.LinkSessionPullRequestResponse], error)
	// Runs the board's inputs on admin connections now, and makes those on device connections due.
	SyncBoard(context.Context, *connect.Request[v1.SyncBoardRequest]) (*connect.Response[v1.SyncBoardResponse], error)
	// The caller's saved filters.
	ListSavedViews(context.Context, *connect.Request[v1.ListSavedViewsRequest]) (*connect.Response[v1.ListSavedViewsResponse], error)
	SaveView(context.Context, *connect.Request[v1.SaveViewRequest]) (*connect.Response[v1.SaveViewResponse], error)
	DeleteSavedView(context.Context, *connect.Request[v1.DeleteSavedViewRequest]) (*connect.Response[v1.DeleteSavedViewResponse], error)
	// The worker on the client: due inputs and pending outputs of the caller's personal boards on these connections, leased.
	ClaimDeviceWork(context.Context, *connect.Request[v1.ClaimDeviceWorkRequest]) (*connect.Response[v1.ClaimDeviceWorkResponse], error)
	ReportDeviceWork(context.Context, *connect.Request[v1.ReportDeviceWorkRequest]) (*connect.Response[v1.ReportDeviceWorkResponse], error)
	// A device connection is gone: same effect as deleting an admin connection, on the caller's own boards.
	ForgetDeviceConnection(context.Context, *connect.Request[v1.ForgetDeviceConnectionRequest]) (*connect.Response[v1.ForgetDeviceConnectionResponse], error)
}

